import{_ as t,o as e,c as i,a2 as r}from"./chunks/framework.Ky-Ipuyb.js";const u=JSON.parse('{"title":"ImGui ガイド","description":"","frontmatter":{"lang":"ja","sourcePath":"docs/imgui/README.ja.md"},"headers":[],"relativePath":"ja/imgui/index.md","filePath":"ja/imgui/index.md"}'),s={name:"ja/imgui/index.md"};function d(l,a,n,o,h,p){return e(),i("div",null,[...a[0]||(a[0]=[r(`<h1 id="imgui-ガイド" tabindex="-1">ImGui ガイド <a class="header-anchor" href="#imgui-ガイド" aria-label="Permalink to &quot;ImGui ガイド&quot;">​</a></h1><p>sfml.js-imgui で SFML ウィンドウにデバッグパネル、シーンインスペクター、ネイティブ編集ツールを作ります。最初のフレームループから、状態編集、テーブル、テキスト入力、フォント、独自描画へ進みます。</p><p>現在のソースは Dear ImGui 1.91.9b と imgui-sfml 3.0 を対象とし、サンプルは JavaScript と SFML 3.1 API を使います。JavaScript と <a href="/ja/guide/window">SFML ウィンドウ</a>の基礎が必要で、C++ は不要です。</p><h2 id="学習の順序" tabindex="-1">学習の順序 <a class="header-anchor" href="#学習の順序" aria-label="Permalink to &quot;学習の順序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章</th><th>作るもの・学ぶこと</th></tr></thead><tbody><tr><td><a href="/ja/imgui/getting-started">クイックスタート</a></td><td>完全なカウンター、フレーム、入力キャプチャ、安全な終了</td></tr><tr><td><a href="/ja/imgui/widgets">ウィジェットと状態</a></td><td>永続状態、固有 ID、リアルタイムのシーン編集</td></tr><tr><td><a href="/ja/imgui/layout">レイアウト</a></td><td>テーブル、メニュー、確認モーダル、スコープの対応</td></tr><tr><td><a href="/ja/imgui/callbacks">入力とコールバック</a></td><td>UTF-8 編集、契約、リスト getter、プロット</td></tr><tr><td><a href="/ja/imgui/fonts">フォントとスタイル</a></td><td>アトラス、CJK、間隔、色、DPI</td></tr><tr><td><a href="/ja/imgui/rendering">描画と複数ウィンドウ</a></td><td>シーン合成、描画リスト、ウィンドウ別の所有権</td></tr><tr><td><a href="/ja/imgui/api">API ガイド</a></td><td>正確なシグネチャ、オーバーロード、寿命の確認</td></tr></tbody></table><p>実践章は完全な実行可能ソースにリンクし、短いコードの配置場所と期待結果も説明します。英語、中国語、日本語、韓国語を提供します。</p><h2 id="サンプルを選ぶ" tabindex="-1">サンプルを選ぶ <a class="header-anchor" href="#サンプルを選ぶ" aria-label="Permalink to &quot;サンプルを選ぶ&quot;">​</a></h2><p>monorepo のルートで bootstrap を一度実行してから起動します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-imgui/examples/demo.cjs</span></span></code></pre></div><ul><li><a href="/ja/examples/imgui#demo">ウィジェットデモ</a>：Dear ImGui 標準のコントロールとレイアウト。</li><li><a href="/ja/examples/imgui#scene-inspector">シーンインスペクター</a>：動く円のサイズ、色、速度を編集。</li><li><a href="/ja/examples/imgui#workbench">workbench</a>：入力、選択、テーブル、モーダル、時間プロットを組み合わせる。</li></ul><h2 id="パッケージの役割" tabindex="-1">パッケージの役割 <a class="header-anchor" href="#パッケージの役割" aria-label="Permalink to &quot;パッケージの役割&quot;">​</a></h2><p>ImGui はコントロール、列挙値、コールバック、ネイティブハンドル操作を提供します。SFML はウィンドウ連携、イベント転送、フレーム送信を担当します。getFontAtlas や getStyleColors はトップレベルのエクスポートです。</p><p>アプリケーション値は JavaScript 所有で、書き込み可能なネイティブスカラーには型付き配列を使います。IO、スタイル、フォント、描画リストはネイティブ所有者と有効期間を持ちます。各章で境界を説明し、正確な契約は <a href="/ja/reference/imgui/" target="_self">API リファレンス</a>で確認できます。</p>`,13)])])}const c=t(s,[["render",d]]);export{u as __pageData,c as default};
